package com.inventario.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.*;
@Entity @Table(name="ventas")
public class Venta { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private Cliente cliente; @Column(nullable=false) private LocalDateTime fecha=LocalDateTime.now(); @Column(nullable=false) private BigDecimal total=BigDecimal.ZERO; @Enumerated(EnumType.STRING) private Estado estado=Estado.COMPLETADA; @OneToMany(mappedBy="venta",cascade=CascadeType.ALL,orphanRemoval=true) private List<DetalleVenta> detalles=new ArrayList<>(); @OneToOne(mappedBy="venta",cascade=CascadeType.ALL) private Factura factura;
 public enum Estado { COMPLETADA, ANULADA } public Long getId(){return id;} public void setId(Long v){id=v;} public Cliente getCliente(){return cliente;} public void setCliente(Cliente v){cliente=v;} public LocalDateTime getFecha(){return fecha;} public void setFecha(LocalDateTime v){fecha=v;} public BigDecimal getTotal(){return total;} public void setTotal(BigDecimal v){total=v;} public Estado getEstado(){return estado;} public void setEstado(Estado v){estado=v;} public List<DetalleVenta> getDetalles(){return detalles;} public void setDetalles(List<DetalleVenta> v){detalles=v;} public Factura getFactura(){return factura;} public void setFactura(Factura v){factura=v;}
}
